import React, { useState } from 'react';
import { User,  Github, Code, Save, Plus, X } from 'lucide-react';

const StudentProfile = () => {
  // إدارة حالة البيانات الشخصية
  const [profile, setProfile] = useState({
    name: "أيوب بن زينة",
    specialty: "Licence 3 - Technologie de l'information",
    email: "ayoub@example.com",
    github: "github.com/ayoub",
    skills: ["React", "Django", "Tailwind"]
  });

  const [newSkill, setNewSkill] = useState("");

  // دالة لإضافة مهارة جديدة ديناميكياً
  const addSkill = () => {
    if (newSkill && !profile.skills.includes(newSkill)) {
      setProfile({ ...profile, skills: [...profile.skills, newSkill] });
      setNewSkill("");
    }
  };

  // دالة لحذف مهارة من القائمة
  const removeSkill = (skillToRemove) => {
    setProfile({
      ...profile,
      skills: profile.skills.filter(skill => skill !== skillToRemove)
    });
  };

  return (
    <div className="max-w-4xl mx-auto p-6" dir="rtl">
      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        {/* الهيدر الأزرق العلوي */}
        <div className="bg-blue-600 h-32"></div>
        
        <div className="px-8 pb-8">
          {/* أيقونة المستخدم الشخصية */}
          <div className="relative -mt-12 mb-6">
            <div className="w-24 h-24 bg-white rounded-2xl shadow-md flex items-center justify-center border-4 border-white">
              <User size={48} className="text-blue-600" />
            </div>
          </div>

          <div className="grid md:grid-cols-2 gap-8">
            {/* قسم المعلومات الشخصية */}
            <div className="space-y-4">
              <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                <User size={20} /> المعلومات الشخصية
              </h2>
              <div>
                <label className="block text-sm text-slate-500 mb-1">الاسم الكامل</label>
                <input 
                  type="text" 
                  value={profile.name}
                  onChange={(e) => setProfile({...profile, name: e.target.value})}
                  className="w-full p-3 bg-slate-50 rounded-xl border-none focus:ring-2 focus:ring-blue-600 outline-none"
                />
              </div>
              <div>
                <label className="block text-sm text-slate-500 mb-1">رابط Github</label>
                <div className="relative">
                  <GitHub className="absolute right-3 top-3 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    value={profile.github}
                    onChange={(e) => setProfile({...profile, github: e.target.value})}
                    className="w-full p-3 pr-10 bg-slate-50 rounded-xl border-none focus:ring-2 focus:ring-blue-600 outline-none"
                  />
                </div>
              </div>
            </div>

            {/* قسم المهارات التفاعلي */}
            <div className="space-y-4">
              <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                <Code size={20} /> المهارات (Skills)
              </h2>
              <div className="flex gap-2 mb-4">
                <input 
                  type="text" 
                  placeholder="أضف مهارة (مثلاً: Java)"
                  value={newSkill}
                  onChange={(e) => setNewSkill(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && addSkill()}
                  className="flex-1 p-3 bg-slate-50 rounded-xl border-none focus:ring-2 focus:ring-blue-600 outline-none"
                />
                <button 
                  onClick={addSkill}
                  className="p-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors"
                >
                  <Plus size={20} />
                </button>
              </div>
              {/* عرض المهارات بشكل مرن (Tags) */}
              <div className="flex flex-wrap gap-2">
                {profile.skills.map((skill, index) => (
                  <span key={index} className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-700 rounded-full font-medium">
                    {skill}
                    <button onClick={() => removeSkill(skill)} className="hover:text-red-500 transition-colors">
                      <X size={14} />
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          {/* زر الحفظ النهائي */}
          <button className="mt-8 w-full py-4 bg-green-600 text-white rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-green-700 shadow-lg shadow-green-100 transition-all">
            <Save size={20} /> حفظ التغييرات
          </button>
        </div>
      </div>
    </div>
  );
};

export default StudentProfile;
